import{_ as l,r as p,o as u,c as i,e as t,a as s,s as e,d as a}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"关联 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"定义关联","slug":"定义关联","link":"#定义关联","children":[{"level":3,"title":"详细定义","slug":"详细定义","link":"#详细定义","children":[]}]},{"level":2,"title":"关联类型","slug":"关联类型","link":"#关联类型","children":[{"level":3,"title":"一对一","slug":"一对一","link":"#一对一","children":[{"level":4,"title":"定义反向关联","slug":"定义反向关联","link":"#定义反向关联","children":[]},{"level":4,"title":"默认模型","slug":"默认模型","link":"#默认模型","children":[]}]},{"level":3,"title":"一对多","slug":"一对多","link":"#一对多","children":[{"level":4,"title":"一对多 (反向)","slug":"一对多-反向","link":"#一对多-反向","children":[]}]},{"level":3,"title":"多对多","slug":"多对多","link":"#多对多","children":[{"level":4,"title":"定义反向关联","slug":"定义反向关联-1","link":"#定义反向关联-1","children":[]},{"level":4,"title":"获取中间表字段","slug":"获取中间表字段","link":"#获取中间表字段","children":[]}]},{"level":3,"title":"远程一对多关联","slug":"远程一对多关联","link":"#远程一对多关联","children":[]},{"level":3,"title":"远程一对一","slug":"远程一对一","link":"#远程一对一","children":[]}]},{"level":2,"title":"多态关联","slug":"多态关联","link":"#多态关联","children":[{"level":3,"title":"多态一对一","slug":"多态一对一","link":"#多态一对一","children":[{"level":4,"title":"表结构","slug":"表结构","link":"#表结构","children":[]},{"level":4,"title":"模型结构","slug":"模型结构","link":"#模型结构","children":[]},{"level":4,"title":"获取关联","slug":"获取关联","link":"#获取关联","children":[]}]},{"level":3,"title":"多态一对多","slug":"多态一对多","link":"#多态一对多","children":[{"level":4,"title":"表结构","slug":"表结构-1","link":"#表结构-1","children":[]},{"level":4,"title":"模型结构","slug":"模型结构-1","link":"#模型结构-1","children":[]},{"level":4,"title":"获取关联","slug":"获取关联-1","link":"#获取关联-1","children":[]}]},{"level":3,"title":"多态多对多","slug":"多态多对多","link":"#多态多对多","children":[{"level":4,"title":"表结构","slug":"表结构-2","link":"#表结构-2","children":[]},{"level":4,"title":"模型结构","slug":"模型结构-2","link":"#模型结构-2","children":[]},{"level":4,"title":"定义反向关联关系","slug":"定义反向关联关系","link":"#定义反向关联关系","children":[]},{"level":4,"title":"获取关联","slug":"获取关联-2","link":"#获取关联-2","children":[]},{"level":4,"title":"自定义多态类型","slug":"自定义多态类型","link":"#自定义多态类型","children":[]}]}]},{"level":2,"title":"查询关联","slug":"查询关联","link":"#查询关联","children":[{"level":3,"title":"通过关联方法访问","slug":"通过关联方法访问","link":"#通过关联方法访问","children":[]},{"level":3,"title":"通过动态属性访问","slug":"通过动态属性访问","link":"#通过动态属性访问","children":[]},{"level":3,"title":"查询已存在的关联","slug":"查询已存在的关联","link":"#查询已存在的关联","children":[]},{"level":3,"title":"关联记录计数","slug":"关联记录计数","link":"#关联记录计数","children":[]}]},{"level":2,"title":"预加载","slug":"预加载","link":"#预加载","children":[{"level":4,"title":"预加载多个关联","slug":"预加载多个关联","link":"#预加载多个关联","children":[]},{"level":4,"title":"嵌套预加载","slug":"嵌套预加载","link":"#嵌套预加载","children":[]},{"level":3,"title":"为预加载添加约束","slug":"为预加载添加约束","link":"#为预加载添加约束","children":[]},{"level":3,"title":"延迟预加载","slug":"延迟预加载","link":"#延迟预加载","children":[]}]},{"level":2,"title":"插入关联模型","slug":"插入关联模型","link":"#插入关联模型","children":[{"level":3,"title":"通过关联方法插入","slug":"通过关联方法插入","link":"#通过关联方法插入","children":[{"level":4,"title":"添加方法","slug":"添加方法","link":"#添加方法","children":[]},{"level":4,"title":"删除方法","slug":"删除方法","link":"#删除方法","children":[]},{"level":4,"title":"使用透视数据添加","slug":"使用透视数据添加","link":"#使用透视数据添加","children":[]},{"level":4,"title":"创建方法","slug":"创建方法","link":"#创建方法","children":[]}]},{"level":3,"title":"通过动态属性插入","slug":"通过动态属性插入","link":"#通过动态属性插入","children":[]},{"level":3,"title":"多对多关联","slug":"多对多关联","link":"#多对多关联","children":[{"level":4,"title":"附加 / 分离","slug":"附加-分离","link":"#附加-分离","children":[]},{"level":4,"title":"同步关联","slug":"同步关联","link":"#同步关联","children":[]}]},{"level":3,"title":"更新父级时间戳","slug":"更新父级时间戳","link":"#更新父级时间戳","children":[]}]},{"level":2,"title":"延迟绑定","slug":"延迟绑定","link":"#延迟绑定","children":[{"level":3,"title":"生成会话密钥","slug":"生成会话密钥","link":"#生成会话密钥","children":[]},{"level":3,"title":"延迟关联绑定","slug":"延迟关联绑定","link":"#延迟关联绑定","children":[]},{"level":3,"title":"推迟解除绑定的关系","slug":"推迟解除绑定的关系","link":"#推迟解除绑定的关系","children":[]},{"level":3,"title":"列出所有绑定","slug":"列出所有绑定","link":"#列出所有绑定","children":[]},{"level":3,"title":"取消所有绑定","slug":"取消所有绑定","link":"#取消所有绑定","children":[]},{"level":3,"title":"提交所有绑定","slug":"提交所有绑定","link":"#提交所有绑定","children":[]},{"level":3,"title":"延迟提交绑定","slug":"延迟提交绑定","link":"#延迟提交绑定","children":[]},{"level":3,"title":"清理无效的绑定","slug":"清理无效的绑定","link":"#清理无效的绑定","children":[]},{"level":3,"title":"禁用延迟绑定","slug":"禁用延迟绑定","link":"#禁用延迟绑定","children":[]}]}],"relativePath":"2.x/zh-cn/database/relations.md","filePath":"2.x/zh-cn/database/relations.md"}'),r={name:"2.x/zh-cn/database/relations.md"};function k(d,n,g,h,m,v){const o=p("pre-heading"),c=p("post-heading");return u(),i("div",null,[t(o),n[0]||(n[0]=s("h1",null,"关联",-1)),t(c),n[1]||(n[1]=e(`<p>数据库表通常相互关联。 例如，一篇博客文章可能有很多评论，或者某个订单可能与发布该订单的用户相关。 October 使管理和处理这些关联变得容易，并支持多种不同类型的关联。</p><h2 id="定义关联"><a href="#定义关联" class="header-anchor">#</a> 定义关联</h2><p>模型关联被定义为模型类的属性。 定义关联的示例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;posts&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Post</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span>
<span class="token punctuation">}</span>
</code></pre></div><p>像模型本身这样的关联也可以作为强大的 <a href="./query.html">查询构建器</a>，将关联作为函数访问提供了强大的方法链接和查询功能。 例如：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">posts</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_active&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>也可以将关联作为属性访问：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">posts</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="oc-detailed-relationships"></a></p><h3 id="详细定义"><a href="#详细定义" class="header-anchor">#</a> 详细定义</h3><p>每个定义都可以是一个数组，其中键是关联名称，值是细节数组。 详细信息数组的第一个值始终是关联模型类名称，所有其他值都是必须具有键名的参数。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;posts&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Post</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;delete&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>以下是可用于所有关联的参数：</p><div class="table"><table tabindex="0"><thead><tr><th>参数</th><th>描述</th></tr></thead><tbody><tr><td><strong>order</strong></td><td>多条记录的排序顺序。</td></tr><tr><td><strong>conditions</strong></td><td>使用原始 where 查询语句过滤关联。</td></tr><tr><td><strong>scope</strong></td><td>使用提供的范围方法过滤关联。</td></tr><tr><td><strong>push</strong></td><td>如果设置为 false，则不会通过 <code>push</code> 保存此关联，默认值：<code>true</code>。</td></tr><tr><td><strong>delete</strong></td><td>如果设置为true，如果主模型被删除或关联被破坏，关联模型将被删除，默认：<code>false</code>。</td></tr><tr><td><strong>replicate</strong></td><td>如果设置为 true，相关模型将通过 <code>replicate</code> 方法复制或关联。 默认值：<code>false</code>。</td></tr><tr><td><strong>relationClass</strong></td><td>为相关对象指定自定义类名。</td></tr></tbody></table></div><p>使用 <strong>order</strong> 和 <strong>conditions</strong> 参数的过滤器示例。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$belongsToMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;categories&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Category</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;order&#39;</span>      <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;name desc&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;conditions&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;is_active = 1&#39;</span>
    <span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>使用 <strong>scope</strong> 参数的示例过滤器。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$belongsToMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;categories&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Category</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;scope&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;isActive&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Category</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">scopeIsActive</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_active&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">orderBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;desc&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p><a id="oc-relationship-types"></a></p><h2 id="关联类型"><a href="#关联类型" class="header-anchor">#</a> 关联类型</h2><p>可以使用以下关联类型：</p><ul><li><a href="#relation-one-to-one">一对一</a></li><li><a href="#relation-one-to-many">一对多</a></li><li><a href="#relation-many-to-many">多对多</a></li><li><a href="#relation-has-many-through">远程一对多</a></li><li><a href="#relation-has-one-through">多态关联</a></li><li><a href="#relation-polymorphic-relations">多对多 (多态关联)</a></li></ul><p><a id="relation-one-to-one"></a></p><h3 id="一对一"><a href="#一对一" class="header-anchor">#</a> 一对一</h3><p>一对一是最基本的关联关系。例如，一个 <code>User</code> 模型可能关联一个 <code>Phone</code> 模型。为了定义这个关联，我们要在 <code>User</code> 模型中写一个 <code>phone</code> 方法。在 <code>phone</code> 方法内部调用 <code>hasOne</code> 方法并返回其结果:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Model</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$hasOne</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;phone&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Phone</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</span></code></pre></div><p><code>hasOne</code> 方法的第一个参数是关联模型的类名。一旦定义了模型关联，我们就可以使用 同名的模型属性检索相关记录。动态属性允许你像访问模型中定义的属性一样访问关联方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$phone</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token property">phone</span><span class="token punctuation">;</span>
</code></pre></div><p>模型会基于模型名决定外键名称。 在这种情况下，会自动假设 <code>Phone</code> 模型有一个 <code>user_id</code> 外键。 如果你想覆盖这个约定，您可以将 <code>key</code> 参数传递定义：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$hasOne</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;phone&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Phone</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;my_user_id&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>此外，该模型假设外键的值应与父级的<code>id</code>字段匹配。 换句话说，它会在<code>Phone</code>记录的<code>user_id</code>列中查找用户表的<code>id</code>字段的值。 如果您希望关联使用 <code>id</code> 以外的定义键名，可以将 <code>otherKey</code> 参数传递定义：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$hasOne</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;phone&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Phone</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;my_user_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;otherKey&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;my_id&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="定义反向关联"><a href="#定义反向关联" class="header-anchor">#</a> 定义反向关联</h4><p>我们已经能从 <code>User</code> 模型访问到 <code>Phone</code> 模型了。现在，让我们再在 <code>Phone</code> 模型上定义一个关联，这个关联能让我们访问到拥有该电话的 <code>User</code> 模型。我们可以使用与 <code>hasOne</code> 方法对应的 <code>belongsTo</code> 方法来定义反向关联：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Phone</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$belongsTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;user&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>User</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>在上面的例子中， 模型会尝试匹配 <code>Phone</code> 模型上的 <code>user_id</code> 至 <code>User</code> 模型上的 <code>id</code> 。它是通过检查关联方法的名称并使用 <code>_id</code> 作为后缀名来确定默认外键名称的。但是，如果 <code>Phone</code> 模型的外键不是 <code>user_id</code>，那么可以将自定义键名作为<code>key</code>参数传递给 <code>belongsTo</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$belongsTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;user&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>User</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;my_user_id&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>如果父级模型没有使用 <code>id</code> 作为主键，或者是希望用不同的字段来连接子级模型，则可以通过给 <code>belongsTo</code> 方法传递<code>otherKey</code>参数的形式指定父级数据表的自定义键：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$belongsTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;user&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>User</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;my_user_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;otherKey&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;my_id&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="默认模型"><a href="#默认模型" class="header-anchor">#</a> 默认模型</h4>`,40)),n[2]||(n[2]=s("p",null,[s("code",null,"belongsTo"),a("关联允许你指定默认模型，当给定关联为 "),s("code",null,"null"),a(" 时，将会返回默认模型。 这种模式被称作 "),s("a",{href:"https://en.wikipedia.org/wiki/Null_Object_pattern",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Null 对象模式"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),s("span",{class:"sr-only"},"(opens new window)")])]),a(" ，可以减少你代码中不必要的检查。在下面的例子中，如果发布的帖子没有找到作者， "),s("code",null,"user"),a(" 关联会返回一个空的 "),s("code",null,"Acme\\Blog\\Models\\User"),a(" 模型：")],-1)),n[3]||(n[3]=e(`<div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$belongsTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;user&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>User</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>如果需要在默认模型里添加属性， 你可以传递数组或者回调方法到 <code>default</code> 中：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$belongsTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;user&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>User</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Guest&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="relation-one-to-many"></a></p><h3 id="一对多"><a href="#一对多" class="header-anchor">#</a> 一对多</h3><p>『一对多』关联用于定义单个模型拥有任意数量的其它关联模型。例如，一篇博客文章可能会有无限多条评论。正如其它所有的模型关联一样，一对多关联的定义也是在 模型中写一个<code>$hasMany</code>方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;comments&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Comment</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>记住一点，模型将会自动确定 <code>Comment</code> 模型的外键属性。按照约定，模型将会使用所属模型名称的 『snake case』形式，再加上 <code>_id</code> 后缀作为外键字段。因此，在上面这个例子中，模型将假定 <code>Comment</code> 对应到 <code>Post</code> 模型上的外键就是 <code>post_id</code>。</p><p>一旦关联被定义好以后，就可以通过访问 <code>Post</code> 模型的 <code>comments</code> 属性来获取评论的集合。记住，由于模型 提供了『动态属性』 ，所以我们可以像访问模型的属性一样访问关联方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$comments</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token property">comments</span><span class="token punctuation">;</span>

<span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$comments</span> <span class="token keyword">as</span> <span class="token variable">$comment</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><p>当然，由于所有的关联还可以作为查询语句构造器使用，因此你可以使用链式调用的方式，在 <code>comments</code> 方法上添加额外的约束条件：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$comments</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">comments</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;title&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>正如 <code>hasOne</code> 方法一样，你也传递 <code>key</code>和<code>otherKey</code>参数来覆盖外键与本地键：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;comments&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Comment</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;my_post_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;otherKey&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;my_id&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="一对多-反向"><a href="#一对多-反向" class="header-anchor">#</a> 一对多 (反向)</h4><p>现在，我们已经能获得一篇文章的所有评论，接着再定义一个通过评论获得所属文章的关联关系。这个关联是 <code>hasMany</code> 关联的反向关联，需要在子级模型中使用 <code>belongsTo</code> 方法定义它：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Comment</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$belongsTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;post&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Post</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>这个关联定义好以后，我们就可以通过访问 <code>Comment</code> 模型的 <code>post</code> 这个『动态属性』来获取关联的 <code>Post</code> 模型了：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$comment</span> <span class="token operator">=</span> <span class="token class-name static-context">Comment</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">echo</span> <span class="token variable">$comment</span><span class="token operator">-&gt;</span><span class="token property">post</span><span class="token operator">-&gt;</span><span class="token property">title</span><span class="token punctuation">;</span>
</code></pre></div><p>在上面的例子中，模型会尝试用 <code>Comment</code> 模型的 <code>post_id</code> 与 <code>Post</code> 模型的 <code>id</code> 进行匹配。默认外键名是 模型依据关联名，并在关联名后加上 <code>_id</code>再加上主键字段名作为后缀确定的。当然，如果 <code>Comment</code> 模型的外键不是 <code>post_id</code>，那么可以将自定义键名作为<code>key</code>参数传递给 <code>belongsTo</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$belongsTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;post&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Post</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;my_post_id&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>如果父级模型没有使用 <code>id</code> 作为主键，或者是希望用不同的字段来连接子级模型，则可以通过给 <code>belongsTo</code> 方法传递<code>otherKey</code>参数的形式指定父级数据表的自定义键：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$belongsTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;post&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Post</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;my_post_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;otherKey&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;my_id&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="relation-many-to-many"></a></p><h3 id="多对多"><a href="#多对多" class="header-anchor">#</a> 多对多</h3><p>多对多关联比 <code>hasOne</code> 和 <code>hasMany</code> 关联稍微复杂些。举个例子，一个用户可以拥有很多种角色，同时这些角色也被其他用户共享。例如，许多用户可能都有 &quot;管理员&quot;这个角色。要定义这种关联，需要三个数据库表： <code>users</code>，<code>roles</code> 和 <code>role_user</code>。<code>role_user</code> 表的命名是由关联的两个模型按照字母顺序来的，并且包含了 <code>user_id</code> 和 <code>role_id</code> 字段。</p><p>下面是一个显示用于创建连接表的<a href="./../plugin/updates.html#oc-migration-files">数据库表结构</a>的示例。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;role_user&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">unsigned</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;role_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">unsigned</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">primary</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;user_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;role_id&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>多对多关联通过调用 <code>belongsToMany</code> 这个内部方法返回的结果来定义，例如，我们在 <code>User</code> 模型中定义 <code>roles</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$belongsToMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;roles&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Role</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>一旦关联关系被定义后，你可以通过 <code>roles</code> 动态属性获取用户角色：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">roles</span> <span class="token keyword">as</span> <span class="token variable">$role</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><p>当然，像其它所有关联模型一样，你可以使用 <code>roles</code> 方法，利用链式调用对查询语句添加约束条件：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$roles</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">roles</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">orderBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>正如前面所提到的，为了确定关联连接表的表名，模型会按照字母顺序连接两个关联模型的名字。当然，你也可以不使用这种约定，传递<code>table</code>参数到 <code>belongsToMany</code> 方法即可</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$belongsToMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;roles&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Role</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;table&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme_blog_role_user&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>除了自定义连接表的表名，你还可以通过传递额外的参数到 <code>belongsToMany</code> 方法来定义该表中字段的键名。<code>key</code>参数是定义此关联的模型在连接表里的外键名，<code>otherKey</code>参数是另一个模型在连接表里的外键名：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$belongsToMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;roles&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Role</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;table&#39;</span>    <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme_blog_role_user&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;key&#39;</span>      <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;my_user_id&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;otherKey&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;my_role_id&#39;</span>
    <span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="定义反向关联-1"><a href="#定义反向关联-1" class="header-anchor">#</a> 定义反向关联</h4><p>要定义多对多的反向关联， 你只需要在关联模型中调用 <code>belongsToMany</code> 方法。我们在 <code>Role</code> 模型中定义 <code>users</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Role</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$belongsToMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;users&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>User</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>如你所见，除了引入模型为 <code>Acme\\Blog\\Models\\User</code> 外，其它与在 <code>User</code> 模型中定义的完全一样。由于我们重用了 <code>belongsToMany</code> 方法，自定义连接表表名和自定义连接表里的键的字段名称在这里同样适用。</p><h4 id="获取中间表字段"><a href="#获取中间表字段" class="header-anchor">#</a> 获取中间表字段</h4><p>就如你刚才所了解的一样，多对多的关联关系需要一个中间表来提供支持， 模型提供了一些有用的方法来和这张表进行交互。例如，假设我们的 <code>User</code> 对象关联了多个 <code>Role</code> 对象。在获得这些关联对象后，可以使用模型的 <code>pivot</code> 属性访问中间表的数据：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">roles</span> <span class="token keyword">as</span> <span class="token variable">$role</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$role</span><span class="token operator">-&gt;</span><span class="token property">pivot</span><span class="token operator">-&gt;</span><span class="token property">created_at</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>需要注意的是，我们获取的每个 <code>Role</code> 模型对象，都会被自动分配一个 <code>pivot</code> 属性，它代表中间表的一个模型对象，并且可以像其他的模型一样使用。</p><p>默认情况下，<code>pivot</code> 对象只包含两个关联模型的主键，如果你的中间表里还有其他额外字段，你必须在定义关联时明确指出：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$belongsToMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;roles&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Role</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;pivot&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;column1&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;column2&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>如果你想让中间表自动维护 <code>created_at</code> 和 <code>updated_at</code> 时间戳，那么在定义关联时附加上 <code>timestamps</code> 方法即可</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$belongsToMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;roles&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Role</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;timestamps&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span>
    <span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>如果你想定义一个自定义模型来表示你关联的中间表，你可以在定义关联时使用 <code>pivotModel</code> 属性。 自定义多对多中间表模型应扩展<code>October\\Rain\\Database\\Pivot</code>类，而自定义多态多对多中间表模型应扩展<code>October\\Rain\\Database\\MorphPivot</code>类。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$belongsToMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;roles&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Role</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;pivotModel&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>UserRolePivot</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>这些是 <code>belongsToMany</code> 关联支持的参数：</p><div class="table"><table tabindex="0"><thead><tr><th>参数</th><th>描述</th></tr></thead><tbody><tr><td><strong>table</strong></td><td>连接表的名称。</td></tr><tr><td><strong>key</strong></td><td>定义模型键的字段名称(在数据透视表内)。 默认值由模型名称和<code>_id</code>后缀组合而成，即<code>user_id</code></td></tr><tr><td><strong>parentKey</strong></td><td>定义模型键的字段名称(在定义模型表中)。 默认值：id</td></tr><tr><td><strong>otherKey</strong></td><td>关联模型键的字段名称(在数据透视表内)。 默认值由模型名称和<code>_id</code>后缀组合而成，即<code>role_id</code></td></tr><tr><td><strong>relatedKey</strong></td><td>关联模型键的字段名称(在关联模型表内)。 默认值：id</td></tr><tr><td><strong>pivot</strong></td><td>在中间表中找到的关联字段数组，属性可通过 <code>$model-&gt;pivot</code> 获得。</td></tr><tr><td><strong>pivotModel</strong></td><td>指定访问中间关联时要返回的自定义模型类。 默认为 <code>October\\Rain\\Database\\Pivot</code> 而对于多态关联为 <code>October\\Rain\\Database\\MorphPivot</code>。</td></tr><tr><td><strong>timestamps</strong></td><td>如果为true，则关联表应包含<code>created_at</code>和<code>updated_at</code>字段。 默认值：false</td></tr></tbody></table></div><p><a id="relation-has-many-through"></a></p><h3 id="远程一对多关联"><a href="#远程一对多关联" class="header-anchor">#</a> 远程一对多关联</h3><p>远程&quot;一对多&quot;关联提供了方便、简短的方式通过中间的关联来获得远层的关联。例如，一个 <code>Country</code> 模型可以通过中间的 <code>User</code> 模型获得多个 <code>Post</code> 模型。在这个例子中，你可以轻易地收集给定国家和地区的所有博客文章。让我们来看看定义这种关联所需的数据表：</p><div class="language- extra-class"><pre class="language-text"><code>countries
    id - integer
    name - string

users
    id - integer
    country_id - integer
    name - string

posts
    id - integer
    user_id - integer
    title - string
</code></pre></div><p>虽然 <code>posts</code> 表中不包含 <code>country_id</code> 字段，但 <code>hasManyThrough</code> 关联能让我们通过 <code>$country-&gt;posts</code> 访问到一个国家下所有的用户文章。为了完成这个查询，模型会先检查中间表 <code>users</code> 的 <code>country_id</code> 字段，找到所有匹配的用户 ID 后，使用这些 ID，在 <code>posts</code> 表中完成查找。</p><p>现在，我们已经知道了定义这种关联所需的数据表结构，接下来，让我们在 <code>Country</code> 模型中定义它：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Country</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$hasManyThrough</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;posts&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Post</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;through&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>User</span><span class="token operator">::</span><span class="token keyword">class</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><code>hasManyThrough</code> 方法的第一个参数是我们最终希望访问的模型名称，而第二个参数是中间模型的名称。</p><p>当执行关联查询时，通常会使用模型约定的外键名。如果你想要自定义关联的键，可以通过给 <code>hasManyThrough</code> 方法传递<code>key</code>, <code>otherKey</code>和<code>throughKey</code>参数实现，<code>key</code>参数表示中间模型的外键名，<code>throughKey</code>参数表示最终模型的外键名。<code>otherKey</code>参数表示本地键名：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$hasManyThrough</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;posts&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Post</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;my_country_id&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;through&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>User</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;throughKey&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;my_user_id&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;otherKey&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;my_id&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="relation-has-one-through"></a></p><h3 id="远程一对一"><a href="#远程一对一" class="header-anchor">#</a> 远程一对一</h3><p>远程一对一关联通过一个中间关联模型实现。 例如，如果每个供应商都有一个用户，并且每个用户与一个用户历史记录相关联，那么供应商可以通过用户访问用户的历史记录，让我们看看定义这种关联所需的数据库表：</p><div class="language- extra-class"><pre class="language-text"><code>users
    id - integer
    supplier_id - integer

suppliers
    id - integer

history
    id - integer
    user_id - integer
</code></pre></div><p>虽然 <code>history</code> 表不包含 <code>supplier_id</code> ，但 <code>hasOneThrough</code> 关联可以提供对用户历史记录的访问，以访问供应商模型。现在我们已经检查了关联的表结构，让我们在 <code>Supplier</code> 模型上定义相应的方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Supplier</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$hasOneThrough</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;userHistory&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Supplies<span class="token punctuation">\\</span>Model<span class="token punctuation">\\</span>History</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;through&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Supplies<span class="token punctuation">\\</span>Model<span class="token punctuation">\\</span>User</span><span class="token operator">::</span><span class="token keyword">class</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>传递给 <code>hasOneThrough</code> 方法的第一个参数是希望访问的模型名称，<code>through</code>参数是中间模型的名称。</p><p>当执行关联查询时，通常会使用模型约定的外键名。如果你想要自定义关联的键，可以通过给 <code>hasManyThrough</code> 方法传递<code>key</code>, <code>otherKey</code>和<code>throughKey</code>参数实现，<code>key</code>参数表示中间模型的外键名，<code>throughKey</code>参数表示最终模型的外键名。<code>otherKey</code>参数表示本地键名：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$hasOneThrough</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;userHistory&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Supplies<span class="token punctuation">\\</span>Model<span class="token punctuation">\\</span>History</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;supplier_id&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;through&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Supplies<span class="token punctuation">\\</span>Model<span class="token punctuation">\\</span>User</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;throughKey&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;user_id&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;otherKey&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;id&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="relation-polymorphic-relations"></a></p><h2 id="多态关联"><a href="#多态关联" class="header-anchor">#</a> 多态关联</h2><p>多态关联允许目标模型借助单个关联从属于多个模型。</p><h3 id="多态一对一"><a href="#多态一对一" class="header-anchor">#</a> 多态一对一</h3><h4 id="表结构"><a href="#表结构" class="header-anchor">#</a> 表结构</h4><p>一对一多态关联与简单的一对一关联类似；不过，目标模型能够在一个关联上从属于多个模型。例如，您的 <code>员工</code> 和 <code>产品</code> 可能共享一个关联到 <code>照片</code> 模型的关系。使用一对一多态关联允许使用一个唯一图片列表同时用于员工列表和产品列表。让我们先看看表结构：</p><div class="language- extra-class"><pre class="language-text"><code>staff
    id - integer
    name - string

products
    id - integer
    price - integer

photos
    id - integer
    path - string
    imageable_id - integer
    imageable_type - string
</code></pre></div><p>要特别留意 <code>photos</code> 表的 <code>imageable_id</code> 和 <code>imageable_type</code> 列。 <code>imageable_id</code> 列包含产品或员工的 ID 值，而 <code>imageable_type</code> 列包含的则是父模型的类名。ORM在访问 <code>imageable</code> 时使用 <code>imageable_type</code> 列来判断父模型的 &quot;类型&quot;</p><h4 id="模型结构"><a href="#模型结构" class="header-anchor">#</a> 模型结构</h4><p>接下来，再看看建立关联的模型定义：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Photo</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$morphTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;imageable&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Staff</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$morphOne</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;photo&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Photo</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;imageable&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Product</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$morphOne</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;photo&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Photo</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;imageable&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="获取关联"><a href="#获取关联" class="header-anchor">#</a> 获取关联</h4><p>一旦定义了表和模型，就可以通过模型访问此关联。比如，要访问员工的照片，可以使用 <code>photo</code> 动态属性：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$staff</span> <span class="token operator">=</span> <span class="token class-name static-context">Staff</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$photo</span> <span class="token operator">=</span> <span class="token variable">$staff</span><span class="token operator">-&gt;</span><span class="token property">photo</span>
</code></pre></div><p>还可以通过访问执行 <code>morphTo</code> 调用的方法名来从多态模型中获知父模型。在这个例子中，就是 <code>Photo</code> 模型的 <code>imageable</code> 方法。所以，我们可以像动态属性那样访问这个方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$photo</span> <span class="token operator">=</span> <span class="token class-name static-context">Photo</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$imageable</span> <span class="token operator">=</span> <span class="token variable">$photo</span><span class="token operator">-&gt;</span><span class="token property">imageable</span><span class="token punctuation">;</span>
</code></pre></div><p><code>Photo</code> 模型的 <code>imageable</code> 关联将返回 <code>Staff</code> 或 <code>Product</code> 实例，其结果取决于图片属性哪个模型。</p><h3 id="多态一对多"><a href="#多态一对多" class="header-anchor">#</a> 多态一对多</h3><h4 id="表结构-1"><a href="#表结构-1" class="header-anchor">#</a> 表结构</h4><p>一对多多态关联与简单的一对多关联类似；不过，目标模型可以在一个关联中从属于多个模型。假设应用中的用户可以同时 &quot;评论&quot; 文章和视频。使用多态关联，可以用单个 <code>comments</code> 表同时满足这些情况。我们还是先来看看用来构建这种关联的表结构：</p><div class="language- extra-class"><pre class="language-text"><code>posts
    id - integer
    title - string
    body - text

videos
    id - integer
    title - string
    url - string

comments
    id - integer
    body - text
    commentable_id - integer
    commentable_type - string
</code></pre></div><h4 id="模型结构-1"><a href="#模型结构-1" class="header-anchor">#</a> 模型结构</h4><p>接下来，看看构建这种关联的模型定义：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Comment</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$morphTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;commentable&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$morphMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;comments&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Comment</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;commentable&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Product</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$morphMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;comments&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Comment</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;commentable&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="获取关联-1"><a href="#获取关联-1" class="header-anchor">#</a> 获取关联</h4><p>一旦定义了数据库表和模型，就可以通过模型访问关联。例如，可以使用 <code>comments</code> 动态属性访问文章的全部评论：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context">Author<span class="token punctuation">\\</span>Plugin<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">comments</span> <span class="token keyword">as</span> <span class="token variable">$comment</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><p>还可以通过访问执行 <code>morphTo</code> 调用的方法名来从多态模型获取其所属模型。在本例中，就是 <code>Comment</code> 模型的 <code>commentable</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$comment</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context">Author<span class="token punctuation">\\</span>Plugin<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Comment</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$commentable</span> <span class="token operator">=</span> <span class="token variable">$comment</span><span class="token operator">-&gt;</span><span class="token property">commentable</span><span class="token punctuation">;</span>
</code></pre></div><p><code>Comment</code> 模型的 <code>commentable</code> 关联将返回 <code>Post</code> 或 <code>Video</code> 实例，其结果取决于评论所属的模型。</p><p>您还可以通过使用 <code>morphTo</code> 关联的名称设置属性来更新关联模型的所有者，在本例中为 <code>commentable</code>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$comment</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context">Author<span class="token punctuation">\\</span>Plugin<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Comment</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$video</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context">Author<span class="token punctuation">\\</span>Plugin<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Video</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$comment</span><span class="token operator">-&gt;</span><span class="token property">commentable</span> <span class="token operator">=</span> <span class="token variable">$video</span><span class="token punctuation">;</span>
<span class="token variable">$comment</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
</code></pre></div><h3 id="多态多对多"><a href="#多态多对多" class="header-anchor">#</a> 多态多对多</h3><h4 id="表结构-2"><a href="#表结构-2" class="header-anchor">#</a> 表结构</h4><p>多对多多态关联比 <code>morphOne</code> 和 <code>morphMany</code> 关联略微复杂一些。例如，博客 <code>Post</code> 和 <code>Video</code> 模型能够共享关联到 <code>Tag</code> 模型的多态关联。使用多对多多态关联允许使用一个唯一标签在博客文章和视频间共享。以下是多对多多态关联的表结构：</p><div class="language- extra-class"><pre class="language-text"><code>posts
    id - integer
    name - string

videos
    id - integer
    name - string

tags
    id - integer
    name - string

taggables
    tag_id - integer
    taggable_id - integer
    taggable_type - string
</code></pre></div><h4 id="模型结构-2"><a href="#模型结构-2" class="header-anchor">#</a> 模型结构</h4><p>接下来，在模型上定义关联。<code>Post</code> 和 <code>Video</code> 模型都有调用基础模型类上 <code>morphToMany</code> 方法的 <code>tags</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$morphToMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;tags&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Tag</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;taggable&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="定义反向关联关系"><a href="#定义反向关联关系" class="header-anchor">#</a> 定义反向关联关系</h4><p>下面，需要在 <code>Tag</code> 模型上为每个关联模型定义一个方法。在这个示例中，我们将会定义 <code>posts</code> 方法和 <code>videos</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Tag</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$morphedByMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;posts&#39;</span>  <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Post</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;taggable&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;videos&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Video</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;taggable&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="获取关联-2"><a href="#获取关联-2" class="header-anchor">#</a> 获取关联</h4><p>一旦定义了数据库表和模型，就可以通过模型访问关联。例如，可以使用 <code>tags</code> 动态属性访问文章的所有标签：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">tags</span> <span class="token keyword">as</span> <span class="token variable">$tag</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><p>还可以访问执行 <code>morphedByMany</code> 方法调用的方法名来从多态模型获取其所属模型。在这个示例中，就是 <code>Tag</code> 模型的 <code>posts</code> 或 <code>videos</code> 方法。可以像动态属性一样访问这些方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$tag</span> <span class="token operator">=</span> <span class="token class-name static-context">Tag</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$tag</span><span class="token operator">-&gt;</span><span class="token property">videos</span> <span class="token keyword">as</span> <span class="token variable">$video</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="自定义多态类型"><a href="#自定义多态类型" class="header-anchor">#</a> 自定义多态类型</h4><p>默认情况下，使用完全限定类名存储关联模型类型。在上面的一对多示例中， 因为 <code>Photo</code> 可能从属于一个 <code>Staff</code> 或一个 <code>Product</code>，默认的 <code>commentable_type</code> 就将分别是 <code>Acme\\Blog\\Models\\Staff</code> 或 <code>Acme\\Blog\\Models\\Product</code>。</p><p>使用自定义多态类型可以让您将数据库与应用程序的内部结构分离。 你可以定义一个关联&quot;变形映射&quot;来为每个模型提供一个自定义名称，而不是类名：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Relations<span class="token punctuation">\\</span>Relation</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Relation</span><span class="token operator">::</span><span class="token function">morphMap</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;staff&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Staff</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;product&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Product</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>在 <a href="./../plugin/registration.html#oc-registration-methods">插件注册文件</a> 的 <code>boot</code> 方法中注册 <code>morphMap</code> 的最常见位置。</p><p><a id="oc-querying-relations"></a></p><h2 id="查询关联"><a href="#查询关联" class="header-anchor">#</a> 查询关联</h2><p>由于模型关联的所有类型都通过方法定义，你可以调用这些方法，而无需真实执行关联查询。另外，所有模型关联类型用作 <a href="./query.html">查询构造器</a>，允许你在数据库上执行 SQL 之前，持续通过链式调用添加约束。</p><p>例如，假设一个博客系统的 <code>User</code> 模型有许多关联的 <code>Post</code>模型：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;posts&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Post</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="通过关联方法访问"><a href="#通过关联方法访问" class="header-anchor">#</a> 通过关联方法访问</h3><p>您可以使用 <code>posts</code> 方法查询 <strong>posts</strong> 关联并为关联添加额外的约束。 这使您能够在关联上扩展任何 <a href="./query.html">查询构造器</a> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$posts</span> <span class="token operator">=</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">posts</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_active&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$post</span> <span class="token operator">=</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">posts</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="通过动态属性访问"><a href="#通过动态属性访问" class="header-anchor">#</a> 通过动态属性访问</h3><p>如果您不需要向关联查询添加额外的约束，您可以简单地访问该关联，就像它是一个属性一样。 例如，继续使用我们的 <code>User</code> 和 <code>Post</code> 示例模型，我们可以使用 <code>$user-&gt;posts</code> 属性来访问用户的所有帖子。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">posts</span> <span class="token keyword">as</span> <span class="token variable">$post</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><p>动态属性是&quot;懒加载&quot;的，这意味着它们仅在你真实访问关联数据时才被载入。因此，开发者经常使用 <a href="#oc-eager-loading">预加载</a> 预先加载那些他们确知在载入模型后将访问的关联。对载入模型关联中必定被执行的 SQL 查询而言，预加载显著减少了查询的执行次数。</p><h3 id="查询已存在的关联"><a href="#查询已存在的关联" class="header-anchor">#</a> 查询已存在的关联</h3><p>在访问模型记录时，可能希望基于关联的存在限制查询结果。比如想要获取至少存在一条评论的所有文章，可以通过给 <code>has</code>方法传递关联名称来实现：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 检索所有至少有一条评论的帖子...</span>
<span class="token variable">$posts</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">has</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>还可以指定运算符和数量进一步自定义查询：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Retrieve all posts that have three or more comments...</span>
<span class="token variable">$posts</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">has</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;=&#39;</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>还可以用&quot;点&quot;语法构造嵌套的 <code>has</code> 语句。比如，可以获取拥有至少一条评论和投票的文章：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 获取拥有至少一条带有投票评论的文章...</span>
<span class="token variable">$posts</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">has</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments.votes&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果需要更多功能，可以使用 <code>whereHas</code> 和 <code>orWhereHas</code> 方法将&quot;where&quot;条件放到 <code>has</code> 查询上。这些方法允许你向关联加入自定义约束，比如检查评论内容：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 获取至少带有一条评论内容包含 foo% 关键词的文章...</span>
<span class="token variable">$posts</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">whereHas</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;content&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;like&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;foo%&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="关联记录计数"><a href="#关联记录计数" class="header-anchor">#</a> 关联记录计数</h3><p>在某些情况下，您可能想要计算在给定关联定义中找到的相关记录的数量。 <code>withCount</code> 方法可用于在所选模型中包含 <code>{relation}_count</code> 列。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">withCount</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;roles&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$users</span> <span class="token keyword">as</span> <span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">roles_count</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><code>withCount</code> 方法支持多个关联以及额外的查询约束。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$posts</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">withCount</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;comments&#39;</span> <span class="token operator">=&gt;</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;content&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;like&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;foo%&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">echo</span> <span class="token variable">$posts</span><span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token operator">-&gt;</span><span class="token property">votes_count</span><span class="token punctuation">;</span>
<span class="token keyword">echo</span> <span class="token variable">$posts</span><span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token operator">-&gt;</span><span class="token property">comments_count</span><span class="token punctuation">;</span>
</code></pre></div><p>您可以使用 <code>loadCount</code> 方法懒加载计数字段。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">loadCount</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;roles&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>还支持其他查询约束。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">loadCount</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;roles&#39;</span> <span class="token operator">=&gt;</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;clearance&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
</code></pre></div><p><a id="oc-eager-loading"></a></p><h2 id="预加载"><a href="#预加载" class="header-anchor">#</a> 预加载</h2><p>当以属性方式访问关联时，关联数据&quot;懒加载&quot;。这意味着直到第一次访问属性时关联数据才会被真实加载。不过 Eloquent 能在查询父模型时&quot;预先载入&quot;子关联。预加载可以缓解 N + 1 查询问题。为了说明 N + 1 查询问题，考虑 <code>Book</code> 模型关联到 <code>Author</code> 的情形：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Book</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$belongsTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;author&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Author</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>现在让我们检索所有书籍及其作者：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$books</span> <span class="token operator">=</span> <span class="token class-name static-context">Book</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$books</span> <span class="token keyword">as</span> <span class="token variable">$book</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$book</span><span class="token operator">-&gt;</span><span class="token property">author</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>此循环将执行一个查询，用于获取全部书籍，然后为每本书执行获取作者的查询。如果我们有 25 本书，此循环将运行 26 个查询：1 个用于查询书籍，25 个附加查询用于查询每本书的作者。</p><p>值得庆幸的是，我们能够使用预加载将操作压缩到只有 2 个查询。在查询时，可以使用 <code>with</code> 方法指定想要预加载的关联：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$books</span> <span class="token operator">=</span> <span class="token class-name static-context">Book</span><span class="token operator">::</span><span class="token function">with</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;author&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$books</span> <span class="token keyword">as</span> <span class="token variable">$book</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$book</span><span class="token operator">-&gt;</span><span class="token property">author</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>在这个例子中，仅执行了两个查询：</p><div class="language-sql extra-class"><pre class="language-sql"><code><span class="token keyword">select</span> <span class="token operator">*</span> <span class="token keyword">from</span> books

<span class="token keyword">select</span> <span class="token operator">*</span> <span class="token keyword">from</span> authors <span class="token keyword">where</span> id <span class="token operator">in</span> <span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">,</span> <span class="token number">5</span><span class="token punctuation">,</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">)</span>
</code></pre></div><h4 id="预加载多个关联"><a href="#预加载多个关联" class="header-anchor">#</a> 预加载多个关联</h4><p>有时，你可能需要在单一操作中预加载几个不同的关联。要达成此目的，只要向 <code>with</code> 方法传递多个关联名称构成的数组参数：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$books</span> <span class="token operator">=</span> <span class="token class-name static-context">Book</span><span class="token operator">::</span><span class="token function">with</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;author&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;publisher&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="嵌套预加载"><a href="#嵌套预加载" class="header-anchor">#</a> 嵌套预加载</h4><p>可以使用&quot;点&quot;语法预加载嵌套关联。比如在一个语句中预加载所有书籍作者及其联系方式：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$books</span> <span class="token operator">=</span> <span class="token class-name static-context">Book</span><span class="token operator">::</span><span class="token function">with</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;author.contacts&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="为预加载添加约束"><a href="#为预加载添加约束" class="header-anchor">#</a> 为预加载添加约束</h3><p>有时，可能希望预加载一个关联，同时为预加载查询添加额外查询条件，就像下面的例子：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">with</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;posts&#39;</span> <span class="token operator">=&gt;</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;title&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;like&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;%first%&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>在这个例子中， 模型将仅预加载那些 <code>title</code> 列包含 <code>first</code> 关键词的文章。也可以调用其它的 <a href="./query.html">查询构造器</a> 方法进一步自定义预加载操作：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">with</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;posts&#39;</span> <span class="token operator">=&gt;</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">orderBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;created_at&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;desc&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="延迟预加载"><a href="#延迟预加载" class="header-anchor">#</a> 延迟预加载</h3><p>有时您可能需要在已检索到父模型后立即加载关联。 例如，如果您需要动态决定是否加载关联模型，这可能很有用：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$books</span> <span class="token operator">=</span> <span class="token class-name static-context">Book</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$someCondition</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$books</span><span class="token operator">-&gt;</span><span class="token function">load</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;author&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;publisher&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>如果您需要在预加载查询上设置额外的查询约束，您可以将 <code>Closure</code> 传递给 <code>load</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$books</span><span class="token operator">-&gt;</span><span class="token function">load</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;author&#39;</span> <span class="token operator">=&gt;</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">orderBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;published_date&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;asc&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="插入关联模型"><a href="#插入关联模型" class="header-anchor">#</a> 插入关联模型</h2><p>就像<a href="#oc-querying-relations">查询关系</a> 一样，October支持使用方法或动态属性方法定义关联。 例如，也许您需要为 <code>Post</code> 模型插入一个新的 <code>Comment</code>。 您可以直接从关联中插入 <code>Comment</code>，而不是手动设置 <code>Comment</code> 上的 <code>post_id</code> 属性。</p><h3 id="通过关联方法插入"><a href="#通过关联方法插入" class="header-anchor">#</a> 通过关联方法插入</h3><p>October为新模型添加关联提供了便捷的方法。 主要可以将模型添加到关联中或从关联中删除。 在每种情况下，分别关联或解除关联。</p><h4 id="添加方法"><a href="#添加方法" class="header-anchor">#</a> 添加方法</h4><p>使用 <code>add</code> 方法关联一个新的关联。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$comment</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Comment</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;message&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;A new comment.&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$comment</span> <span class="token operator">=</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">comments</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token variable">$comment</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>请注意，我们没有将 <code>comments</code> 关联作为动态属性访问。 相反，我们调用 <code>comments</code> 方法来获取关联的实例。 <code>add</code> 方法会自动将适当的 <code>post_id</code> 值添加到新的 <code>Comment</code> 模型中。</p><p>如果需要保存多个相关模型，可以使用 <code>addMany</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">comments</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">addMany</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token keyword">new</span> <span class="token class-name">Comment</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;message&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;A new comment.&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token keyword">new</span> <span class="token class-name">Comment</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;message&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Another comment.&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="删除方法"><a href="#删除方法" class="header-anchor">#</a> 删除方法</h4><p>相比之下，<code>remove</code> 方法可用于解除关联关系，使其成为无效记录。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">comments</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">remove</span><span class="token punctuation">(</span><span class="token variable">$comment</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>在多对多关联的情况下，记录将从关联的集合中删除。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">categories</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">remove</span><span class="token punctuation">(</span><span class="token variable">$category</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>在&quot;belongsTo&quot;关联的情况下，您可以使用 <code>dissociate</code> 方法，该方法不需要将相关模型传递给它。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">author</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">dissociate</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="使用透视数据添加"><a href="#使用透视数据添加" class="header-anchor">#</a> 使用透视数据添加</h4><p>当处理多对多关系时，<code>add</code> 方法接受一个额外的中间&quot;透视&quot;表属性数组作为其第二个参数作为数组。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$pivotData</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;expires&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$expires</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">roles</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token variable">$role</span><span class="token punctuation">,</span> <span class="token variable">$pivotData</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>add</code> 方法的第二个参数还可以指定 <a href="#oc-deferred-binding">延迟绑定</a> 在作为字符串传递时使用的会话密钥。 在这些情况下，可以将透视数据作为第三个参数提供。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">roles</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token variable">$role</span><span class="token punctuation">,</span> <span class="token variable">$sessionKey</span><span class="token punctuation">,</span> <span class="token variable">$pivotData</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="创建方法"><a href="#创建方法" class="header-anchor">#</a> 创建方法</h4><p>虽然 <code>add</code> 和 <code>addMany</code> 接受完整的模型实例，但您也可以使用 <code>create</code> 方法，该方法接受 PHP 属性数组，创建模型并将其插入数据库。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$comment</span> <span class="token operator">=</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">comments</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;message&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;A new comment.&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>在使用 <code>create</code> 方法之前，请务必查看有关属性 <a href="./model.html#oc-mass-assignment">批量赋值</a> 的文档，因为 PHP 数组中的属性受模型的&quot;可填充&quot;定义的限制。</p><h3 id="通过动态属性插入"><a href="#通过动态属性插入" class="header-anchor">#</a> 通过动态属性插入</h3><p>可以通过它们的属性直接设置关联，就像您访问它们一样。 使用这种方法设置关联将覆盖以前存在的任何关联。 之后应该像使用任何属性一样保存模型。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">author</span> <span class="token operator">=</span> <span class="token variable">$author</span><span class="token punctuation">;</span>

<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">comments</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token variable">$comment1</span><span class="token punctuation">,</span> <span class="token variable">$comment2</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>或者，您可以使用主键设置关联，这在处理 HTML 表单时很有用。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 分配给 ID 为 3 的作者</span>
<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">author</span> <span class="token operator">=</span> <span class="token number">3</span><span class="token punctuation">;</span>

<span class="token comment">// 分配 ID 为 1、2 和 3 的评论</span>
<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">comments</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>可以通过将 NULL 值分配给属性来解除关联。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">author</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">;</span>

<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">comments</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">;</span>

<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>与 <a href="#oc-deferred-binding">延迟绑定</a> 类似，在不存在的模型上定义的关联在内存中被延迟，直到它们被保存。 在此示例中，帖子尚不存在，因此无法通过 <code>$post-&gt;comments</code> 在评论上设置 <code>post_id</code> 属性。 因此，关联会延迟到通过调用<code>save</code>方法创建帖子为止。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$comment</span> <span class="token operator">=</span> <span class="token class-name static-context">Comment</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$post</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Post</span><span class="token punctuation">;</span>

<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">comments</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token variable">$comment</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="多对多关联"><a href="#多对多关联" class="header-anchor">#</a> 多对多关联</h3><h4 id="附加-分离"><a href="#附加-分离" class="header-anchor">#</a> 附加 / 分离</h4><p>在处理多对多关系时，模型也提供了一些额外的辅助方法，使相关模型的使用更加方便。例如，我们假设一个用户可以拥有多个角色，并且每个角色都可以被多个用户共享。给某个用户附加一个角色是通过向中间表插入一条记录实现的，可以使用 <code>attach</code> 方法完成该操作:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">roles</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">attach</span><span class="token punctuation">(</span><span class="token variable">$roleId</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>在将关系附加到模型时，还可以传递一组要插入到中间表中的附加数据：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">roles</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">attach</span><span class="token punctuation">(</span><span class="token variable">$roleId</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;expires&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$expires</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>当然，有时也需要移除用户的角色。可以使用 <code>detach</code> 移除多对多关联记录。<code>detach</code> 方法将会移除中间表对应的记录；但是这 2 个模型都将会保留在数据库中：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 移除用户的一个角色...</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">roles</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">detach</span><span class="token punctuation">(</span><span class="token variable">$roleId</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 移除用户的所有角色...</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">roles</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">detach</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>为了方便，<code>attach</code> 和 <code>detach</code> 也允许传递一个 ID 数组：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">roles</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">detach</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">roles</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">attach</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;expires&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$expires</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="同步关联"><a href="#同步关联" class="header-anchor">#</a> 同步关联</h4><p>你也可以使用 <code>sync</code> 方法构建多对多关联。<code>sync</code> 方法接收一个 ID 数组以替换中间表的记录。中间表记录中，所有未在 ID 数组中的记录都将会被移除。所以该操作结束后，只有给出数组的 ID 会被保留在中间表中：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">roles</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">sync</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>你也可以通过 ID 传递额外的附加数据到中间表：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">roles</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">sync</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;expires&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="更新父级时间戳"><a href="#更新父级时间戳" class="header-anchor">#</a> 更新父级时间戳</h3><p>当一个模型属 <code>belongsTo</code> 或者 <code>belongsToMany</code> 另一个模型时， 例如 <code>Comment</code> 属于 <code>Post</code>，有时更新子模型导致更新父模型时间戳非常有用。例如，当 <code>Comment</code> 模型被更新时，您要自动&quot;触发&quot;父级 <code>Post</code> 模型的 <code>updated_at</code> 时间戳的更新。只要在子模型加一个包含关联名称的 <code>touches</code> 属性即可：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Comment</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * 要触发的所有关联关系
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$touches</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;post&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token comment">/**
     * Relations
     */</span>
    <span class="token keyword">public</span> <span class="token variable">$belongsTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;post&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Post</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>现在，当你更新一个 <code>Comment</code> 时，对应父级 <code>Post</code> 模型的 <code>updated_at</code> 字段同时也会被更新：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$comment</span> <span class="token operator">=</span> <span class="token class-name static-context">Comment</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$comment</span><span class="token operator">-&gt;</span><span class="token property">text</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;编辑此评论!&#39;</span><span class="token punctuation">;</span>

<span class="token variable">$comment</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="oc-deferred-binding"></a></p><h2 id="延迟绑定"><a href="#延迟绑定" class="header-anchor">#</a> 延迟绑定</h2><p>延迟绑定允许您延迟绑定模型关联，直到主记录提交更改。如果您需要准备一些模型(例如文件上传)并将它们关联到另一个尚不存在的模型，这将特别有用。</p><p>您可以使用 <strong>session key</strong> 将任意数量的 <strong>slave</strong> 模型延迟保定到 <strong>master</strong> 模型。当主记录与会话键一起保存时，与从属记录的关联会自动为您更新。后端 <a href="./../backend/form.html">表单行为</a> 自动支持延迟绑定，但您可能希望在其他地方使用此功能。</p><h3 id="生成会话密钥"><a href="#生成会话密钥" class="header-anchor">#</a> 生成会话密钥</h3><p>延迟绑定需要会话密钥。您可以将会话密钥视为事务标识符。相同的会话密钥应该用于绑定/解除绑定关联和保存主模型。您可以使用 PHP <code>uniqid()</code> 函数生成会话密钥。请注意，<a href="./../markup/function-form.html">表单助手</a> 会自动生成一个包含会话密钥的隐藏字段。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$sessionKey</span> <span class="token operator">=</span> <span class="token function">uniqid</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;session_key&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="延迟关联绑定"><a href="#延迟关联绑定" class="header-anchor">#</a> 延迟关联绑定</h3><p>除非帖子被保存，否则下一个示例中的评论不会添加到帖子中。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$comment</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Comment</span><span class="token punctuation">;</span>
<span class="token variable">$comment</span><span class="token operator">-&gt;</span><span class="token property">content</span> <span class="token operator">=</span> <span class="token string double-quoted-string">&quot;Hello world!&quot;</span><span class="token punctuation">;</span>
<span class="token variable">$comment</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$post</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Post</span><span class="token punctuation">;</span>
<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">comments</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token variable">$comment</span><span class="token punctuation">,</span> <span class="token variable">$sessionKey</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>注意</strong>：<code>$post</code> 对象尚未保存，但如果保存，将创建关联。</p></blockquote><h3 id="推迟解除绑定的关系"><a href="#推迟解除绑定的关系" class="header-anchor">#</a> 推迟解除绑定的关系</h3><p>除非保存帖子，否则不会删除下一个示例中的评论。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$comment</span> <span class="token operator">=</span> <span class="token class-name static-context">Comment</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">comments</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">remove</span><span class="token punctuation">(</span><span class="token variable">$comment</span><span class="token punctuation">,</span> <span class="token variable">$sessionKey</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="列出所有绑定"><a href="#列出所有绑定" class="header-anchor">#</a> 列出所有绑定</h3><p>使用关联的 <code>withDeferred</code> 方法加载所有记录，包括延迟的。 结果也将包括现有关系。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">comments</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withDeferred</span><span class="token punctuation">(</span><span class="token variable">$sessionKey</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="取消所有绑定"><a href="#取消所有绑定" class="header-anchor">#</a> 取消所有绑定</h3><p>取消延迟绑定并删除从属对象而不是让它们成为无效对象是个好主意.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">cancelDeferred</span><span class="token punctuation">(</span><span class="token variable">$sessionKey</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="提交所有绑定"><a href="#提交所有绑定" class="header-anchor">#</a> 提交所有绑定</h3><p>您可以在保存主模型时提交(绑定或取消绑定)所有延迟绑定，方法是为<code>save</code>方法的第二个参数提供会话密钥。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Post</span><span class="token punctuation">;</span>
<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">title</span> <span class="token operator">=</span> <span class="token string double-quoted-string">&quot;First blog post&quot;</span><span class="token punctuation">;</span>
<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token constant">null</span><span class="token punctuation">,</span> <span class="token variable">$sessionKey</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>同样的方法适用于模型的 <code>create</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;First blog post&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token variable">$sessionKey</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="延迟提交绑定"><a href="#延迟提交绑定" class="header-anchor">#</a> 延迟提交绑定</h3><p>如果您在保存时无法提供 <code>$sessionKey</code>，您可以随时使用以下代码提交绑定：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">commitDeferred</span><span class="token punctuation">(</span><span class="token variable">$sessionKey</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="清理无效的绑定"><a href="#清理无效的绑定" class="header-anchor">#</a> 清理无效的绑定</h3><p>销毁所有尚未提交且超过 1 天的绑定：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name class-name-fully-qualified static-context">October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>DeferredBinding</span><span class="token operator">::</span><span class="token function">cleanUp</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>注意</strong>：October CMS 会自动销毁超过 5 天的延迟绑定。 当后端用户登录系统时会触发。</p></blockquote><h3 id="禁用延迟绑定"><a href="#禁用延迟绑定" class="header-anchor">#</a> 禁用延迟绑定</h3><p>有时您可能需要完全禁用给定模型的延迟绑定，例如，如果您从单独的数据库连接加载它。 您需要确保模型的 <code>sessionKey</code> 属性在内部保存方法中的 pre 和 post 延迟绑定钩子运行之前为 <code>null</code>。 为此，您可以绑定到模型的 <code>model.saveInternal</code> 事件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$result</span> <span class="token operator">=</span> <span class="token keyword static-context">parent</span><span class="token operator">::</span><span class="token function">__construct</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token function">func_get_args</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.saveInternal&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">sessionKey</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token variable">$result</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><blockquote><p><strong>注意</strong>：这将为您覆盖此应用的任何模型完全禁用延迟绑定。</p></blockquote>`,273))])}const f=l(r,[["render",k]]);export{y as __pageData,f as default};
